	ctx.restore();
	ctx.save();
	ctx.transform(0.390625,0.0,0.0,0.390625,354.0,380.0);
	font2(ctx,"4",textColor);
	ctx.restore();
	ctx.save();
	ctx.transform(0.390625,0.0,0.0,0.390625,572.0,380.0);
